sys_script.script:
(function executeRule(current, previous /*null when async*/) {




	var grSignTask = new GlideRecord("sn_hr_core_task");
	grSignTask.initialize();

	grSignTask.parent = current.getValue("sys_id");
	grSignTask.state = 18;
	grSignTask.hr_task_type = "e_sign";
	grSignTask.short_description = "Manager Signature Required (ESDC Form LAB1069) - "+current.number;
	grSignTask.sn_esign_esignature_configuration = "af7e3d0eb7743300a251e556ee11a939";
	grSignTask.sys_user_group = "CEH-HRS-OHS-Admin";
	grSignTask.assigned_to = current.manager_name;//current.subject_person.manager;

	grSignTask.insert();





})(current, previous);
